import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.map.js";
import { ref, onMounted, onUnmounted, computed } from 'vue';
import { useRouter } from 'vue-router';
import { useStore } from 'vuex';
import axios from 'axios';
import DOMPurify from 'dompurify';
import defaultAvatar from '@/assets/default-avatar.png';
import { API_CONFIG } from '@/config/config';
import { ElMessage } from 'element-plus';
import emojis from '@/utils/emojis';
export default {
  setup() {
    // 表情相关状态
    const emojiList = ref(emojis);
    const showCommentEmojiPicker = ref(false);
    const showReplyEmojiPicker = ref(false);
    const activeReplyComment = ref(null);
    const commentEditor = ref(null);
    const router = useRouter();
    const store = useStore();
    const moment = ref({});
    const currentUser = computed(() => store.state.user || {});
    const goToUser = () => router.push('/user');
    const goToUserProfile = userId => router.push(`/user/${userId}`);

    // 切换表情面板
    const toggleEmojiPicker = (type, comment = null) => {
      if (type === 'comment') {
        showCommentEmojiPicker.value = !showCommentEmojiPicker.value;
        showReplyEmojiPicker.value = false;
      } else {
        activeReplyComment.value = comment;
        showReplyEmojiPicker.value = !showReplyEmojiPicker.value;
        showCommentEmojiPicker.value = false;
      }
    };

    // 插入表情
    const insertEmoji = (emoji, type, comment = null) => {
      try {
        let editor;
        if (type === 'comment') {
          editor = commentEditor.value;
        } else {
          editor = comment ? document.querySelector(`[ref='replyEditor_${comment.id}']`) : null;
        }
        if (!editor) return;
        const selection = window.getSelection();
        const range = selection.getRangeAt(0);
        const textNode = document.createTextNode(emoji);
        range.insertNode(textNode);
        range.collapse(false);
        updateCommentContent();
      } catch (error) {
        console.error('插入表情失败:', error);
      }
    };

    // 更新评论内容
    const updateCommentContent = () => {
      if (commentEditor.value) {
        moment.value.commentInput = DOMPurify.sanitize(commentEditor.value.innerHTML);
      }
    };
    const getFullUrl = path => {
      if (!path || path === defaultAvatar) return path;
      return path.startsWith('http') ? path : `${API_CONFIG.BASE_URL}${path}`;
    };
    const formatTime = timestamp => {
      const date = new Date(timestamp);
      return `${date.getFullYear()}-${(date.getMonth() + 1).toString().padStart(2, '0')}-` + `${date.getDate().toString().padStart(2, '0')} ` + `${date.getHours().toString().padStart(2, '0')}:` + `${date.getMinutes().toString().padStart(2, '0')}`;
    };
    const getTimeAgo = timestamp => {
      const now = Date.now();
      const diff = now - new Date(timestamp).getTime();
      const minutes = Math.floor(diff / 60000);
      const hours = Math.floor(minutes / 60);
      const days = Math.floor(hours / 24);
      if (minutes < 1) return '刚刚';
      if (minutes < 60) return `${minutes}分钟前`;
      if (hours < 24) return `${hours}小时前`;
      return `${days}天前`;
    };
    const sanitizeHtml = html => DOMPurify.sanitize(html);
    const fetchMomentDetail = async momentId => {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/article/moment`, {
          params: {
            moment_id: momentId
          },
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        const momentData = response.data;
        moment.value = {
          ...momentData,
          showCommentInput: false,
          commentInput: '',
          comments: (momentData.comments || []).map(comment => ({
            ...comment,
            showReplyInput: false,
            replyInput: '',
            replies: comment.replies || []
          })),
          showAllComments: false,
          isLiked: momentData.like_users?.includes(currentUser.value.id) || false
        };
      } catch (error) {
        console.error('获取动态详情失败:', error);
        ElMessage.error('加载动态详情失败');
      }
    };
    const toggleCommentInput = moment => {
      moment.showCommentInput = !moment.showCommentInput;
      moment.commentInput = '';
    };
    const postComment = async moment => {
      if (!moment.commentInput.trim()) return;
      try {
        const content = {
          text: DOMPurify.sanitize(moment.commentInput),
          html: moment.commentInput
        };
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/post_comment`, {
          moment_id: moment.id,
          comment: JSON.stringify(content),
          comment_user_name: currentUser.value.username,
          comment_user_id: currentUser.value.id
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          // 在数组开头添加新评论
          moment.comments.unshift({
            id: response.data.id,
            comment: moment.commentInput,
            created_at: new Date().toISOString(),
            comment_user_name: currentUser.value.username,
            comment_user_photo: currentUser.value.photo,
            likes: 0,
            isLiked: false,
            replies: []
          });
          // 更新评论数量
          moment.stats.comments += 1;
          // 清空输入框并关闭
          moment.commentInput = '';
          moment.showCommentInput = false;
          ElMessage.success('评论发布成功');
        }
      } catch (error) {
        console.error('评论失败:', error);
        ElMessage.error('评论发布失败');
      }
    };
    const toggleReplyInput = comment => {
      comment.showReplyInput = !comment.showReplyInput;
      comment.replyInput = '';
    };
    const postReply = async (moment, comment) => {
      if (!comment.replyInput.trim()) return;
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/post_reply`, {
          moment_id: moment.id,
          parent_comment_id: comment.id,
          comment: comment.replyInput,
          comment_user_id: currentUser.value.id
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          comment.replies.push({
            ...response.data.reply,
            comment_user_name: currentUser.value.username,
            comment_user_photo: currentUser.value.photo
          });
          comment.replyInput = '';
          comment.showReplyInput = false;
          ElMessage.success('回复成功');
        }
      } catch (error) {
        console.error('回复失败:', error);
        ElMessage.error('回复失败');
      }
    };
    const likeMoment = async momentId => {
      const targetMoment = moment.value;
      if (!targetMoment) return;

      // 保存原始状态用于回滚
      const originalIsLiked = targetMoment.isLiked;
      const originalLikes = targetMoment.stats.likes;
      try {
        // 立即更新UI状态
        targetMoment.isLiked = !targetMoment.isLiked;
        targetMoment.stats.likes += targetMoment.isLiked ? 1 : -1;
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/like_moment`, {
          moment_id: momentId,
          user_id: currentUser.value.id,
          is_like: targetMoment.isLiked
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          },
          timeout: 5000 // 增加超时控制
        });
        if (response.data.success) {
          // 检查 stats 是否存在，如果不存在则初始化
          if (!targetMoment.stats) {
            targetMoment.stats = {
              likes: 0
            };
          }
          // 更新前端状态
          targetMoment.isLiked = response.data.likes > targetMoment.stats.likes;
          targetMoment.stats.likes = response.data.likes;
          ElMessage.success(targetMoment.isLiked ? '点赞成功' : '已取消点赞');

          // 精确同步后端数据
          targetMoment.isLiked = response.data.is_liked;
          targetMoment.stats.likes = response.data.likes_count;

          // 更新like_users列表
          if (response.data.is_liked) {
            targetMoment.like_users = [...(targetMoment.like_users || []), currentUser.value.id];
          } else {
            targetMoment.like_users = (targetMoment.like_users || []).filter(id => id !== currentUser.value.id);
          }
        }
      } catch (error) {
        // 回滚状态
        targetMoment.isLiked = originalIsLiked;
        targetMoment.stats.likes = originalLikes;
        console.error('点赞操作失败:', error);
        ElMessage.error(`操作失败: ${error.response?.data?.msg || '网络错误'}`);
      }
    };
    const likeComment = async (momentId, commentIndex) => {
      const comment = moment.value.comments[commentIndex];
      if (!comment) return;
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/article/like_comment`, {
          comment_id: comment.id,
          user_id: currentUser.value.id
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        comment.isLiked = response.data.is_liked;
        comment.likes = response.data.likes_count;
      } catch (error) {
        console.error('点赞失败:', error);
        ElMessage.error(`点赞失败: ${error.response?.data?.msg || '网络错误'}`);
      }
    };
    const deleteMoment = async momentId => {
      try {
        await axios.post(`${API_CONFIG.BASE_URL}/article/delete/moment`, {
          moment_id: momentId
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        router.back(); // 删除后返回上一页
        ElMessage.success('删除成功');
      } catch (error) {
        console.error('删除失败:', error);
        ElMessage.error('删除失败');
      }
    };
    const visibleComments = moment => {
      return moment.showAllComments ? moment.comments : moment.comments.slice(0, 3);
    };
    onMounted(() => {
      const route = router.currentRoute.value;
      const momentId = route.params.momentId;
      if (momentId) {
        fetchMomentDetail(momentId);
      }
      if (!Array.isArray(emojiList.value)) {
        console.error('表情数据格式错误，使用默认表情');
        emojiList.value = ['😀', '😃', '😄', '😁', '😆', '😅', '😂', '🤣'];
      }
    });
    onUnmounted(() => {
      // 可添加一些清理操作相关逻辑，这里目前无特殊清理需求
    });
    return {
      // 新增返回的属性和方法
      emojiList,
      showCommentEmojiPicker,
      toggleEmojiPicker,
      insertEmoji,
      showReplyEmojiPicker,
      moment,
      currentUser,
      getFullUrl,
      formatTime,
      getTimeAgo,
      sanitizeHtml,
      goToUser,
      goToUserProfile,
      toggleCommentInput,
      postComment,
      toggleReplyInput,
      postReply,
      likeMoment,
      likeComment,
      deleteMoment,
      visibleComments,
      defaultAvatar
    };
  }
};
